INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Ingeniero de movilidad", "en": "Mobility engineer", "source": "Mobility engineer"}, "biography": {"es": "Trabajo en proyectos de movilidad urbana y espacios públicos. Los fines de semana salgo en bicicleta y cocino con amigos.", "en": "I work on urban mobility and public space projects. On weekends I cycle and cook with friends.", "source": "I work on urban mobility and public space projects. On weekends I cycle and cook with friends."}}', '64894dc4a54d5d72809e9e2c16a6a45e', '1991-09-23', 'Hombre', 'Valencia, España', 'Valencia, España', 'Mobility engineer', 'I work on urban mobility and public space projects. On weekends I cycle and cook with friends.', '', 'https://example.invalid/adrian-navarro', '[]', '2646c0bf4a4f5cb3bb8a8fde5858d6c4', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
INSERT INTO "user_profiles" ("display_text", "user_id", "birthday", "gender", "hometown", "location", "headline", "biography", "phone", "website", "social_links", "avatar_media_id", "cv_bytes", "cv_filename", "cv_mime_type", "cv_sha256", "cv_text", "cv_context", "cv_status", "cv_error", "cv_simulated", "cv_updated_at", "created_at") VALUES ('{"headline": {"es": "Diseñadora de comunicación", "en": "Communication designer", "source": "Communication designer"}, "biography": {"es": "Diseño contenidos para iniciativas culturales y comunitarias. Me gustan la lectura, la fotografía y los paseos por el parque.", "en": "I design content for cultural and community initiatives. I enjoy reading, photography and walks in the park.", "source": "I design content for cultural and community initiatives. I enjoy reading, photography and walks in the park."}}', 'd93eec11a6435f87aeae7ae2922735c9', '1994-03-12', 'Mujer', 'Medellín, Colombia', 'Medellín, Colombia', 'Communication designer', 'I design content for cultural and community initiatives. I enjoy reading, photography and walks in the park.', '', 'https://example.invalid/paula-mendez', '[]', '10138b2f9c255eab82156e14bd1a83fc', NULL, NULL, NULL, NULL, NULL, NULL, 'empty', NULL, FALSE, NULL, '2026-11-04 14:14:57');
